WITH parsed AS (SELECT id, coupon_codes, ship_to, SIZE(FILTER(items, x -> x.qty >= 3)) AS bulk_lines, ship_to.zip AS ship_zip, COALESCE(attributes['device'], 'unknown') AS device_or_default FROM carts) SELECT CASE WHEN bulk_lines >= 3 THEN 'LARGE' ELSE 'SMALL' END AS bulk_lines_tier, ROUND(AVG(bulk_lines), 2) AS avg_bulk_lines, COUNT(*) AS event_count FROM parsed GROUP BY CASE WHEN bulk_lines >= 3 THEN 'LARGE' ELSE 'SMALL' END ORDER BY bulk_lines_tier;
